using EduOS.Core.Common;
using EduOS.Core.DTOs.HR;
using EduOS.Core.Entities.Attendance;
using EduOS.Core.Entities.Employees;
using EduOS.Core.Entities.Payroll;
using EduOS.Core.Interfaces;
using EduOS.Core.Interfaces.IRepositories;
using EduOS.Core.Interfaces.IServices;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using System.Security.Cryptography;
namespace EduOS.Service.Services.HR;
public sealed class HrPayrollService:IHrPayrollService
{
 private readonly IGenericRepository<Employee> _employees;private readonly IGenericRepository<EmployeeAttendance> _attendance;private readonly IGenericRepository<SalaryStructure> _salary;private readonly IGenericRepository<Payroll> _payroll;private readonly IGenericRepository<Bonus> _bonuses;private readonly IGenericRepository<LoanAdvance> _loans;private readonly IUnitOfWork _uow;private readonly ICurrentUserService _user;private readonly TimeProvider _clock;private readonly ILogger<HrPayrollService> _log;
 public HrPayrollService(IGenericRepository<Employee> employees,IGenericRepository<EmployeeAttendance> attendance,IGenericRepository<SalaryStructure> salary,IGenericRepository<Payroll> payroll,IGenericRepository<Bonus> bonuses,IGenericRepository<LoanAdvance> loans,IUnitOfWork uow,ICurrentUserService user,TimeProvider clock,ILogger<HrPayrollService> log){_employees=employees;_attendance=attendance;_salary=salary;_payroll=payroll;_bonuses=bonuses;_loans=loans;_uow=uow;_user=user;_clock=clock;_log=log;}
 public async Task<ApiResponse<bool>> SaveSalaryStructureAsync(SaveSalaryStructureDto r,CancellationToken ct=default)
 {if(!CanManage())return ApiResponse<bool>.ErrorResponse("Payroll access is required.",403);var e=await _employees.GetQueryable().FirstOrDefaultAsync(x=>x.TenantId==_user.TenantId&&x.PublicId==r.EmployeeReference&&x.IsActive,ct);if(e==null)return ApiResponse<bool>.ErrorResponse("Employee not found.",404);var now=_clock.GetUtcNow().UtcDateTime;var old=await _salary.GetQueryable().Where(x=>x.TenantId==_user.TenantId&&x.EmployeeId==e.Id&&x.IsActive).ToListAsync(ct);foreach(var x in old){x.IsActive=false;x.UpdatedAt=now;x.UpdatedBy=_user.UserId;}var gross=r.BasicSalary+r.HouseRent+r.Medical+r.Transport+r.Others;await _salary.AddAsync(new SalaryStructure{TenantId=_user.TenantId,EmployeeId=e.Id,BasicSalary=r.BasicSalary,HouseRent=r.HouseRent,Medical=r.Medical,Transport=r.Transport,Others=r.Others,GrossSalary=gross,EffectiveFrom=r.EffectiveFrom.Date,IsActive=true,CreatedAt=now,CreatedBy=_user.UserId});e.Salary=gross;e.UpdatedAt=now;e.UpdatedBy=_user.UserId;await _uow.SaveChangesAsync(ct);return ApiResponse<bool>.SuccessResponse(true,"Salary structure saved.");}
 public async Task<ApiResponse<int>> SaveAttendanceAsync(SaveEmployeeAttendanceDto r,CancellationToken ct=default)
 {if(!CanHr())return ApiResponse<int>.ErrorResponse("HR attendance access is required.",403);if(r.Items.GroupBy(x=>x.EmployeeReference).Any(g=>g.Count()>1))return ApiResponse<int>.ErrorResponse("Duplicate employees were supplied.");var refs=r.Items.Select(x=>x.EmployeeReference).ToArray();var emps=await _employees.GetQueryable().AsNoTracking().Where(x=>x.TenantId==_user.TenantId&&refs.Contains(x.PublicId)&&x.IsActive).ToListAsync(ct);if(emps.Count!=refs.Distinct().Count())return ApiResponse<int>.ErrorResponse("One or more employees are unavailable.",409);var ids=emps.Select(x=>x.Id).ToArray();var rows=await _attendance.GetQueryable().Where(x=>x.TenantId==_user.TenantId&&x.Date.Date==r.Date.Date&&ids.Contains(x.EmployeeId)).ToListAsync(ct);var by=rows.ToDictionary(x=>x.EmployeeId);var now=_clock.GetUtcNow().UtcDateTime;foreach(var item in r.Items){var e=emps.First(x=>x.PublicId==item.EmployeeReference);if(!by.TryGetValue(e.Id,out var a)){a=new EmployeeAttendance{TenantId=_user.TenantId,EmployeeId=e.Id,Date=r.Date.Date,CreatedAt=now,CreatedBy=_user.UserId};await _attendance.AddAsync(a);}a.Status=item.Status;a.InTime=item.InTime;a.OutTime=item.OutTime;a.OvertimeHours=item.OvertimeHours;a.Remarks=Trim(item.Remarks);a.UpdatedAt=now;a.UpdatedBy=_user.UserId;}await _uow.SaveChangesAsync(ct);return ApiResponse<int>.SuccessResponse(r.Items.Count,"Employee attendance saved.");}
 public async Task<ApiResponse<PayrollBatchDto>> GeneratePayrollAsync(GeneratePayrollDto r,CancellationToken ct=default)
 {if(!CanManage())return ApiResponse<PayrollBatchDto>.ErrorResponse("Payroll access is required.",403);if(r.ClientRequestId==Guid.Empty)return ApiResponse<PayrollBatchDto>.ErrorResponse("Client request reference is required.");var month=r.Month.ToString("D2");var start=new DateTime(r.Year,r.Month,1);var end=start.AddMonths(1).AddTicks(-1);var t=_user.TenantId;var prior=await _payroll.GetQueryable().AsNoTracking().Include(x=>x.Employee).Where(x=>x.TenantId==t&&x.GenerationRequestId==r.ClientRequestId).ToListAsync(ct);if(prior.Count>0){if(prior.Any(x=>x.Month!=month||x.Year!=r.Year))return ApiResponse<PayrollBatchDto>.ErrorResponse("Client request reference was already used for another period.",409);return ApiResponse<PayrollBatchDto>.SuccessResponse(new PayrollBatchDto{ClientRequestId=r.ClientRequestId,Existing=prior.Count,Rows=prior.Select(Map).ToList()},"Payroll request was already processed.");}var employees=await _employees.GetQueryable().AsNoTracking().Where(x=>x.TenantId==t&&x.IsActive&&x.JoiningDate<=end).OrderBy(x=>x.EmployeeCode).ToListAsync(ct);var result=new PayrollBatchDto{ClientRequestId=r.ClientRequestId};var now=_clock.GetUtcNow().UtcDateTime;try{foreach(var e in employees){var old=await _payroll.GetQueryable().Include(x=>x.Employee).FirstOrDefaultAsync(x=>x.TenantId==t&&x.EmployeeId==e.Id&&x.Month==month&&x.Year==r.Year,ct);if(old!=null){result.Existing++;result.Rows.Add(Map(old));continue;}var s=await _salary.GetQueryable().AsNoTracking().Where(x=>x.TenantId==t&&x.EmployeeId==e.Id&&x.IsActive&&x.EffectiveFrom<=end).OrderByDescending(x=>x.EffectiveFrom).FirstOrDefaultAsync(ct);if(s==null)continue;var absent=await _attendance.CountAsync(x=>x.TenantId==t&&x.EmployeeId==e.Id&&x.Date>=start&&x.Date<=end&&x.Status=="Absent");var attendanceDeduction=Math.Round(s.GrossSalary/DateTime.DaysInMonth(r.Year,r.Month)*absent,2);var bonus=await _bonuses.GetQueryable().AsNoTracking().Where(x=>x.TenantId==t&&x.EmployeeId==e.Id&&x.BonusMonth==month&&x.BonusYear==r.Year).SumAsync(x=>(decimal?)x.Amount,ct)??0m;var loans=await _loans.GetQueryable().AsNoTracking().Where(x=>x.TenantId==t&&x.EmployeeId==e.Id&&(x.Status=="Approved"||x.Status=="Paid")&&x.RemainingAmount>0).ToListAsync(ct);var loanDeduction=loans.Sum(x=>Math.Min(x.MonthlyDeduction,x.RemainingAmount));var gross=s.GrossSalary;var deductions=attendanceDeduction+loanDeduction;var net=Math.Max(0m,gross+bonus-deductions);var publicId=Guid.NewGuid();var p=new Payroll{TenantId=t,PublicId=publicId,GenerationRequestId=r.ClientRequestId,BillingKey=$"{r.Year:D4}-{r.Month:D2}-{e.Id}",EmployeeId=e.Id,Employee=e,Month=month,Year=r.Year,GrossSalary=gross,AbsentDays=absent,AttendanceDeduction=attendanceDeduction,LoanDeduction=loanDeduction,Deductions=deductions,Bonus=bonus,NetSalary=net,Status="Pending",CreatedAt=now,CreatedBy=_user.UserId};await _payroll.AddAsync(p);result.Generated++;result.Rows.Add(Map(p));}await _uow.SaveChangesAsync(ct);var refs=result.Rows.Select(x=>x.Reference).ToArray();var saved=await _payroll.GetQueryable().AsNoTracking().Include(x=>x.Employee).Where(x=>x.TenantId==t&&refs.Contains(x.PublicId)).ToListAsync(ct);result.Rows=saved.OrderBy(x=>x.Employee!.EmployeeCode).Select(Map).ToList();return ApiResponse<PayrollBatchDto>.SuccessResponse(result,"Payroll generated.");}catch(DbUpdateException ex){_log.LogWarning(ex,"Payroll generation conflict for tenant {TenantId}",t);return ApiResponse<PayrollBatchDto>.ErrorResponse("Payroll conflicts with an existing period.",409);}}
 public async Task<ApiResponse<PayrollRowDto>> PayAsync(PayPayrollDto r,CancellationToken ct=default)
 {if(!CanManage()||!TryVersion(r.RowVersion,out var v))return ApiResponse<PayrollRowDto>.ErrorResponse("Payroll payment request is invalid.",400);try{await _uow.BeginTransactionAsync();var p=await _payroll.GetQueryable().Include(x=>x.Employee).FirstOrDefaultAsync(x=>x.TenantId==_user.TenantId&&x.PublicId==r.PayrollReference,ct);if(p==null)return await Rollback("Payroll not found.",404);if(!VersionsMatch(p.RowVersion,v))return await Rollback("Payroll changed by another user. Reload and try again.",409);if(p.Status=="Paid")return await Rollback("Payroll is already paid.",409);var now=_clock.GetUtcNow().UtcDateTime;var remainingDeduction=p.LoanDeduction;var loans=await _loans.GetQueryable().Where(x=>x.TenantId==_user.TenantId&&x.EmployeeId==p.EmployeeId&&(x.Status=="Approved"||x.Status=="Paid")&&x.RemainingAmount>0).OrderBy(x=>x.RequestDate).ToListAsync(ct);foreach(var loan in loans){if(remainingDeduction<=0)break;var d=Math.Min(remainingDeduction,Math.Min(loan.MonthlyDeduction,loan.RemainingAmount));loan.TotalDeducted+=d;loan.RemainingAmount-=d;loan.Status=loan.RemainingAmount<=0?"Completed":"Paid";loan.UpdatedAt=now;loan.UpdatedBy=_user.UserId;remainingDeduction-=d;}var bonuses=await _bonuses.GetQueryable().Where(x=>x.TenantId==_user.TenantId&&x.EmployeeId==p.EmployeeId&&x.BonusMonth==p.Month&&x.BonusYear==p.Year&&x.PaidDate==null).ToListAsync(ct);foreach(var b in bonuses){b.PaidDate=now;b.UpdatedAt=now;b.UpdatedBy=_user.UserId;}p.Status="Paid";p.PaymentDate=now;p.PaymentMethod=r.PaymentMethod;p.Note=Trim(r.Note);p.PaidByUserId=_user.UserId;p.UpdatedAt=now;p.UpdatedBy=_user.UserId;await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync();return ApiResponse<PayrollRowDto>.SuccessResponse(Map(p),"Payroll marked paid.");}catch(DbUpdateConcurrencyException ex){await SafeRollback();_log.LogWarning(ex,"Concurrent payroll payment {Reference}",r.PayrollReference);return ApiResponse<PayrollRowDto>.ErrorResponse("Payroll changed by another user.",409);}catch(Exception ex){await SafeRollback();_log.LogError(ex,"Payroll payment failed {Reference}",r.PayrollReference);return ApiResponse<PayrollRowDto>.ErrorResponse("Payroll payment failed.",500);}}
 public async Task<ApiResponse<IReadOnlyList<PayrollRowDto>>> GetMyPayrollAsync(CancellationToken ct=default)
 {if(!_user.IsAuthenticated||_user.TenantId<=0)return ApiResponse<IReadOnlyList<PayrollRowDto>>.ErrorResponse("Authentication is required.",403);var e=await _employees.GetQueryable().AsNoTracking().FirstOrDefaultAsync(x=>x.TenantId==_user.TenantId&&x.UserId==_user.UserId,ct);if(e==null)return ApiResponse<IReadOnlyList<PayrollRowDto>>.ErrorResponse("Employee profile is not linked to this account.",403);IReadOnlyList<PayrollRowDto> rows=await _payroll.GetQueryable().AsNoTracking().Include(x=>x.Employee).Where(x=>x.TenantId==_user.TenantId&&x.EmployeeId==e.Id).OrderByDescending(x=>x.Year).ThenByDescending(x=>x.Month).Select(x=>new PayrollRowDto{Reference=x.PublicId,EmployeeReference=e.PublicId,EmployeeCode=e.EmployeeCode,EmployeeName=e.FullName,Month=x.Month,Year=x.Year,GrossSalary=x.GrossSalary,AbsentDays=x.AbsentDays,AttendanceDeduction=x.AttendanceDeduction,LoanDeduction=x.LoanDeduction,Bonus=x.Bonus,NetSalary=x.NetSalary,Status=x.Status,PaymentDate=x.PaymentDate,RowVersion=Convert.ToBase64String(x.RowVersion)}).ToListAsync(ct);return ApiResponse<IReadOnlyList<PayrollRowDto>>.SuccessResponse(rows);}
 private bool CanHr()=>_user.IsAuthenticated&&_user.TenantId>0&&(_user.IsTenantAdmin||_user.IsInRole("Principal")||_user.IsInRole("HRManager"));private bool CanManage()=>CanHr()||_user.IsInRole("Accountant");
 private static PayrollRowDto Map(Payroll x)=>new(){Reference=x.PublicId,EmployeeReference=x.Employee?.PublicId??Guid.Empty,EmployeeCode=x.Employee?.EmployeeCode??string.Empty,EmployeeName=x.Employee?.FullName??string.Empty,Month=x.Month,Year=x.Year,GrossSalary=x.GrossSalary,AbsentDays=x.AbsentDays,AttendanceDeduction=x.AttendanceDeduction,LoanDeduction=x.LoanDeduction,Bonus=x.Bonus,NetSalary=x.NetSalary,Status=x.Status,PaymentDate=x.PaymentDate,RowVersion=Convert.ToBase64String(x.RowVersion)};
 private static string? Trim(string? v)=>string.IsNullOrWhiteSpace(v)?null:v.Trim();private static bool TryVersion(string? s,out byte[] v){try{v=Convert.FromBase64String(s??"");return v.Length>0;}catch{v=[];return false;}}private static bool VersionsMatch(byte[] a,byte[] b)=>a.Length==b.Length&&CryptographicOperations.FixedTimeEquals(a,b);private async Task<ApiResponse<PayrollRowDto>> Rollback(string m,int c){await SafeRollback();return ApiResponse<PayrollRowDto>.ErrorResponse(m,c);}private async Task SafeRollback(){try{await _uow.RollbackTransactionAsync();}catch(Exception ex){_log.LogError(ex,"Payroll rollback failed.");}}
}
